import * as React from "react";
import * as THREE from "three";

export interface IsometricCubesSceneProps {
  className?: string;
  wireframe?: boolean;
  color?: string;
  speed?: number;
}

/**
 * Isometric Cubes Scene
 * Hardware-accelerated 3D WebGL scene with procedural geometry and pointer interaction.
 */
export function IsometricCubesScene({
  className = "w-full h-full min-h-[300px]",
  wireframe = false,
  color = "#ba442c",
  speed = 1.0,
}: IsometricCubesSceneProps): React.JSX.Element {
  const containerRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(45, container.clientWidth / container.clientHeight, 0.1, 1000);
    camera.position.z = 4.5;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(container.clientWidth, container.clientHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(renderer.domElement);

    const ambientLight = new THREE.AmbientLight(0xffffff, 0.7);
    scene.add(ambientLight);
    const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight.position.set(5, 5, 5);
    scene.add(dirLight);

    let geometry: THREE.BufferGeometry;
    if ("isometric-cubes-scene".includes("globe") || "isometric-cubes-scene".includes("sphere")) {
      geometry = new THREE.IcosahedronGeometry(1.6, 12);
    } else if ("isometric-cubes-scene".includes("cube") || "isometric-cubes-scene".includes("isometric")) {
      geometry = new THREE.BoxGeometry(1.4, 1.4, 1.4);
    } else if ("isometric-cubes-scene".includes("nebula") || "isometric-cubes-scene".includes("particle")) {
      geometry = new THREE.BufferGeometry();
      const count = 3000;
      const positions = new Float32Array(count * 3);
      for (let i = 0; i < count * 3; i++) positions[i] = (Math.random() - 0.5) * 6;
      geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
      const mat = new THREE.PointsMaterial({ color: new THREE.Color(color), size: 0.04 });
      const points = new THREE.Points(geometry, mat);
      scene.add(points);
      let animId: number;
      const animate = () => {
        points.rotation.y += 0.0012 * speed;
        renderer.render(scene, camera);
        animId = requestAnimationFrame(animate);
      };
      animate();
      return () => {
        cancelAnimationFrame(animId);
        renderer.dispose();
        geometry.dispose();
        if (container.contains(renderer.domElement)) container.removeChild(renderer.domElement);
      };
    } else {
      geometry = new THREE.TorusKnotGeometry(1.2, 0.35, 128, 32);
    }

    const material = new THREE.MeshStandardMaterial({ color: new THREE.Color(color), wireframe, metalness: 0.85, roughness: 0.2 });
    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    let targetRotX = 0, targetRotY = 0;
    const onPointerMove = (e: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      targetRotY = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      targetRotX = -(((e.clientY - rect.top) / rect.height) * 2 - 1);
    };
    container.addEventListener("pointermove", onPointerMove);

    let animId: number;
    const animate = () => {
      mesh.rotation.x += (targetRotX * 0.8 - mesh.rotation.x) * 0.05 + 0.003;
      mesh.rotation.y += (targetRotY * 0.8 - mesh.rotation.y) * 0.05 + 0.006;
      renderer.render(scene, camera);
      animId = requestAnimationFrame(animate);
    };
    animate();

    const onResize = () => {
      if (!container) return;
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(container.clientWidth, container.clientHeight);
    };
    window.addEventListener("resize", onResize);

    return () => {
      cancelAnimationFrame(animId);
      container.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("resize", onResize);
      renderer.dispose();
      geometry.dispose();
      material.dispose();
      if (container.contains(renderer.domElement)) container.removeChild(renderer.domElement);
    };
  }, [color, wireframe, speed]);

  return <div ref={containerRef} className={className} />;
}

import * as React from "react";
import { IsometricCubesScene } from "./isometric-cubes-scene";

export default function IsometricCubesSceneDemo(): React.JSX.Element {
  return (
    <div className="flex min-h-[460px] w-full items-center justify-center overflow-hidden rounded-2xl bg-neutral-950 p-6 border border-neutral-800">
      <div className="relative h-[380px] w-full max-w-xl">
        <IsometricCubesScene className="h-full w-full" />
      </div>
    </div>
  );
}
